#include <sycl/sycl.hpp>
#include <sycl/ext/intel/math.hpp>
#include <cmath>
#include <bit>
#include <iostream>
struct Result {float d,ratio,rounded,drn,ratio_rn,rounded_rn,sycl_round;};
int main(){sycl::queue q;auto* out=sycl::malloc_shared<Result>(512*1025,q);
q.parallel_for(sycl::range<1>(512*1025),[=](sycl::id<1> id){int m=id[0]/1025+1,i=int(id[0]%1025)-512;float a=float(m)/4096.f,x=float(i)/4096.f;
float d=a/127.f,r=x/d,drn=sycl::ext::intel::math::fdiv_rn(a,127.f),rrn=sycl::ext::intel::math::fdiv_rn(x,drn);
out[id]={d,r,roundf(r),drn,rrn,roundf(rrn),sycl::round(rrn)};}).wait_and_throw();
size_t dm=0,rm=0,qm=0,drm=0,rrm=0,qrm=0,srm=0;
for(int m=1;m<=512;++m)for(int i=-m;i<=m;++i){float a=float(m)/4096.f,x=float(i)/4096.f,d=a/127.f,r=x/d,round=std::round(r);auto g=out[(m-1)*1025+i+512];
auto ne=[](float a,float b){return std::bit_cast<unsigned>(a)!=std::bit_cast<unsigned>(b);};dm+=ne(g.d,d);rm+=ne(g.ratio,r);drm+=ne(g.drn,d);rrm+=ne(g.ratio_rn,r);qm+=g.rounded!=round;qrm+=g.rounded_rn!=round;srm+=g.sycl_round!=round;
if((g.rounded!=round||g.rounded_rn!=round||g.sycl_round!=round)&&i>0)std::cout<<"m="<<m<<" i="<<i<<" cpu="<<std::hexfloat<<d<<' '<<r<<' '<<round<<" gpu="<<g.d<<' '<<g.ratio<<' '<<g.rounded<<" rn="<<g.drn<<' '<<g.ratio_rn<<' '<<g.rounded_rn<<' '<<g.sycl_round<<std::defaultfloat<<'\n';}
std::cout<<"mismatch d/r/q="<<dm<<'/'<<rm<<'/'<<qm<<" RN="<<drm<<'/'<<rrm<<'/'<<qrm<<" sycl_round="<<srm<<'\n';sycl::free(out,q);}
